864:       if (tempPenalty > 2) stress += Math.min(4, tempPenalty / 2);
865:       // Variación sintética entre corridas para enseñar sensibilidad; no es una tasa empírica.
866:       if (rand() < 0.08) stress += 3 + rand() * 5;
867:       if (strat.stress && d % (strat.stressEvery || 3) === 0) stress += strat.stress;
868:       health = Math.max(15, Math.min(99, health + (stress ? -stress : 0.55)));
