let batchCache = null;
function currentBatch() {
  if (app.batch && Array.isArray(app.batch.runs)) return app.batch;
  if (!batchCache) {
    batchCache = { seed: 7, runs: BATCH_STRATEGIES.map(s => simulateBatch(s.id, 7)), sample: true };
  }
  return batchCache;
}

