(function (root, factory) {
  const api = factory();
  if (typeof module === 'object' && module.exports) module.exports = api;
  if (root) root.VerdeBackup = api;
})(typeof window !== 'undefined' ? window : globalThis, function () {
  'use strict';

  const FORMAT = 'verde-backup';
  const VERSION = 1;
  const MAX_FILE_BYTES = 50 * 1024 * 1024;

  function assertSafeTree(value, depth = 0, budget = { nodes: 200000 }) {
    if (depth > 80 || --budget.nodes < 0) throw new Error('El respaldo es demasiado complejo.');
    if (!value || typeof value !== 'object') return;
    for (const key of Object.keys(value)) {
      if (key === '__proto__' || key === 'prototype' || key === 'constructor') {
        throw new Error('El respaldo contiene campos no permitidos.');
      }
      assertSafeTree(value[key], depth + 1, budget);
    }
  }

  function createBackup(game, app, exportedAt = new Date().toISOString()) {
    return {
      format: FORMAT,
      version: VERSION,
      exportedAt,
      pdfsIncluded: false,
      data: { game, app }
    };
  }

  function parseBackup(text) {
    if (typeof text !== 'string' || text.length > MAX_FILE_BYTES) {
      throw new Error('El archivo supera el tamaño máximo de 50 MB.');
    }
    let backup;
    try { backup = JSON.parse(text); }
    catch { throw new Error('El archivo no contiene un JSON válido.'); }

    assertSafeTree(backup);
    if (!backup || backup.format !== FORMAT || backup.version !== VERSION || backup.pdfsIncluded !== false) {
      throw new Error('El formato del respaldo no es compatible.');
    }
    const data = backup.data;
    if (!data || !data.game || typeof data.game !== 'object' || Array.isArray(data.game) ||
        !Array.isArray(data.game.plants) || data.game.plants.length > 100 ||
        !Array.isArray(data.game.logs) || data.game.logs.length > 10000 ||
        !data.app || typeof data.app !== 'object' || Array.isArray(data.app) ||
        !data.app.budget || typeof data.app.budget !== 'object' || Array.isArray(data.app.budget) ||
        !Array.isArray(data.app.userResources) || data.app.userResources.length > 5000) {
      throw new Error('El respaldo está incompleto o tiene una estructura inválida.');
    }
    if (data.game.plants.some(plant => !plant || typeof plant !== 'object' || Array.isArray(plant)) ||
        data.app.userResources.some(resource => !resource || typeof resource !== 'object' || Array.isArray(resource))) {
      throw new Error('El respaldo contiene registros inválidos.');
    }
    return data;
  }

  return { createBackup, parseBackup, MAX_FILE_BYTES };
});

'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { createBackup, parseBackup } = require('../backup-core.js');

const sample = () => ({
  game: { day: 12, plants: [{ id: 1, health: 90 }], logs: [] },
  app: { budget: { plants: 9 }, userResources: [{ id: 'notes', mdText: '# Nota' }] }
});

test('exporta e vuelve a leer un respaldo con versión explícita y sin PDFs', () => {
  const data = sample();
  const backup = createBackup(data.game, data.app, '2026-11-07T00:00:00.000Z');
  assert.equal(backup.format, 'verde-backup');
  assert.equal(backup.version, 1);
  assert.equal(backup.pdfsIncluded, false);
  assert.deepEqual(parseBackup(JSON.stringify(backup)), data);
});

test('rechaza JSON mal formado, formatos desconocidos y estructura incompleta', () => {
  assert.throws(() => parseBackup('{'), /JSON válido/);
  assert.throws(() => parseBackup(JSON.stringify({ format: 'otro', version: 1 })), /compatible/);
  assert.throws(() => parseBackup(JSON.stringify(createBackup({}, {}))), /estructura inválida/);
});

test('rechaza claves peligrosas y colecciones fuera de los límites', () => {
  const malicious = JSON.parse(JSON.stringify(createBackup(...Object.values(sample()))));
  malicious.data.app.__proto__ = { polluted: true };
  assert.throws(() => parseBackup(JSON.stringify(malicious)), /campos no permitidos/);

  const tooManyPlants = sample();
  tooManyPlants.game.plants = Array(101).fill({ id: 1 });
  assert.throws(() => parseBackup(JSON.stringify(createBackup(tooManyPlants.game, tooManyPlants.app))), /estructura inválida/);
});

