})(typeof window !== 'undefined' ? window : globalThis, function () {
  'use strict';

  const MAX_SCENARIOS = 6;
  const clamp = (value, min, max, fallback) => {
    const number = Number(value);
    return Number.isFinite(number) ? Math.max(min, Math.min(max, number)) : fallback;
  };

  function normalizeConfig(config = {}) {
    return {
      strainId: typeof config.strainId === 'string' ? config.strainId.slice(0, 120) : '',
      plants: Math.round(clamp(config.plants, 1, 9, 9)),
      days: Math.round(clamp(config.days, 55, 90, 75)),
      light: clamp(config.light, 12, 24, 18),
      temp: clamp(config.temp, 18, 32, 24),
      strategy: typeof config.strategy === 'string' ? config.strategy.slice(0, 60) : 'balanced'
    };
  }

  function normalizeScenarios(list) {
    if (!Array.isArray(list)) return [];
    const scenarios = [];
    const names = new Set();
    for (const item of list) {
      if (!item || typeof item.name !== 'string' || !item.config || typeof item.config !== 'object') continue;
      const name = item.name.trim().slice(0, 40);
      const key = name.toLocaleLowerCase('es');
      if (!name || names.has(key)) continue;
      scenarios.push({ name, config: normalizeConfig(item.config) });
      names.add(key);
      if (scenarios.length === MAX_SCENARIOS) break;
    }
    return scenarios;
  }

  function saveScenario(list, name, config) {
    const scenarios = normalizeScenarios(list);
    const cleanName = typeof name === 'string' ? name.trim().slice(0, 40) : '';
    if (!cleanName) return { scenarios, error: 'Ingresá un nombre para guardar el escenario.' };
    const existing = scenarios.findIndex(item => item.name.toLocaleLowerCase('es') === cleanName.toLocaleLowerCase('es'));
    if (existing < 0 && scenarios.length >= MAX_SCENARIOS) {
      return { scenarios, error: `Podés guardar hasta ${MAX_SCENARIOS} escenarios.` };
    }
    const saved = { name: cleanName, config: normalizeConfig(config) };
    if (existing < 0) scenarios.push(saved);
    else scenarios[existing] = saved;
    return { scenarios, saved, error: null };
  }

  function removeScenario(list, name) {
    const key = typeof name === 'string' ? name.toLocaleLowerCase('es') : '';
    return normalizeScenarios(list).filter(item => item.name.toLocaleLowerCase('es') !== key);
  }

  return { MAX_SCENARIOS, normalizeConfig, normalizeScenarios, saveScenario, removeScenario };
});

'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { MAX_SCENARIOS, normalizeScenarios, saveScenario, removeScenario } = require('../scenario-core.js');

const config = { strainId: 'demo', plants: 4, days: 70, light: 18, temp: 24, strategy: 'balanced' };

test('guarda escenarios nombrados y normaliza límites de configuración', () => {
  const result = saveScenario([], '  Mi batch  ', { ...config, plants: 100, temp: 'NaN' });
  assert.equal(result.error, null);
  assert.equal(result.scenarios[0].name, 'Mi batch');
  assert.equal(result.scenarios[0].config.plants, 9);
  assert.equal(result.scenarios[0].config.temp, 24);
});

test('un nombre repetido actualiza el escenario sin ocupar otro cupo', () => {
  let result = saveScenario([], 'Verano', config);
  result = saveScenario(result.scenarios, 'verano', { ...config, plants: 2 });
  assert.equal(result.scenarios.length, 1);
  assert.equal(result.scenarios[0].config.plants, 2);
});

test('limita a seis escenarios nuevos y permite eliminar para liberar un cupo', () => {
  let scenarios = [];
  for (let i = 0; i < MAX_SCENARIOS; i++) {
    scenarios = saveScenario(scenarios, `Batch ${i + 1}`, config).scenarios;
  }
  const rejected = saveScenario(scenarios, 'Séptimo', config);
  assert.match(rejected.error, /hasta 6/);
  scenarios = removeScenario(scenarios, 'Batch 2');
  assert.equal(saveScenario(scenarios, 'Séptimo', config).scenarios.length, MAX_SCENARIOS);
});

test('normaliza datos importados malformados, nombres duplicados y cantidades excesivas', () => {
  const list = normalizeScenarios([
    { name: ' Uno ', config },
    { name: 'uno', config },
    { name: 'Dos', config: { ...config, days: -2 } },
    ...Array.from({ length: 8 }, (_, i) => ({ name: `Extra ${i}`, config }))
  ]);
  assert.equal(list.length, MAX_SCENARIOS);
  assert.equal(list[0].name, 'Uno');
  assert.equal(list[1].config.days, 55);
});

